const body = $input.first().json.body;
const required = ['request_id', 'story_id', 'brand_id'];
const missing = required.filter(f => !body[f]);
if (missing.length > 0) return [];
const ALL = ['linkedin_post','blog','video_guide','carousel'];
let formats = Array.isArray(body.formats) && body.formats.length ? body.formats.filter(f => ALL.includes(f)) : ALL;
if (!formats.length) formats = ALL;
return [{ json: { request_id: body.request_id, story_id: body.story_id, brand_id: body.brand_id, formats } }];

const story = $('Fetch Story').first().json;
const brand = $input.first().json;
const requested_formats = $('Validate Input').first().json.formats || ['linkedin_post','blog','video_guide','carousel'];
const lowContext = !brand.voice_rules || !brand.banned_patterns ||   !brand.gold_examples || Object.keys(brand.gold_examples || {}).length === 0;
return [{ json: {
  requested_formats,
  story_id: story.id,
  brand_id: brand.id,
  story_title: story.title,
  story_summary: story.summary,
  source_quote: story.source_quote,
  voice_rules: brand.voice_rules || '',
  banned_patterns: brand.banned_patterns || [],
  gold_examples: brand.gold_examples || {},
  icp_description: brand.icp_description || '',
  colour_primary: brand.colour_primary || '#000000',
  colour_secondary: brand.colour_secondary || '#ffffff',
  colour_accent: brand.colour_accent || '#0066cc',
  low_context: lowContext
} }];

const brief = $('Compile Brief').first().json;
const ALL = ['linkedin_post','blog','video_guide','carousel'];
const requested = (brief.requested_formats && brief.requested_formats.length) ? brief.requested_formats : ALL;
const existing = new Set($('Fetch Existing Pieces').all().map(i => i.json && i.json.format).filter(Boolean));
const toGenerate = requested.filter(f => !existing.has(f));
const base = 'You are a professional content writer.\n\n'  + 'STORY TITLE: ' + brief.story_title + '\n'  + 'STORY SUMMARY: ' + brief.story_summary + '\n'  + 'SOURCE QUOTE: ' + brief.source_quote + '\n\n'  + (brief.voice_rules ? 'BRAND VOICE RULES: ' + brief.voice_rules + '\n\n' : '')  + (brief.icp_description ? 'TARGET AUDIENCE: ' + brief.icp_description + '\n\n' : '')  + 'SOUND HUMAN, NOT AI-GENERATED. Follow these rules strictly:\n'  + '- Never use em dashes. Use commas, colons or full stops instead.\n'  + '- Never use these words or phrases: delve, tapestry, testament, moreover, furthermore, seamless, robust, elevate, unlock, embark, realm, foster, underscore, pivotal, meticulous, navigate the landscape, in todays fast-paced world, at the end of the day, in conclusion, when it comes to.\n'  + '- Avoid the formulaic setup of stating what something is not, only to flip to what it is; and avoid the pattern of calling something not just one thing but another.\n'  + '- Vary sentence length and structure. Do not begin consecutive sentences the same way. Do not force every list into three items.\n'  + '- No emoji. No hashtag stuffing. No tidy summary paragraph that just restates the point.\n'  + '- Write the way a sharp founder would actually talk to a smart peer, with specifics over adjectives.\n\n';

const formats = [
  {
    format: 'linkedin_post',
    systemPrompt: base + (brief.gold_examples.linkedin_post && brief.gold_examples.linkedin_post.length ? 'GOLD EXAMPLES:\n' + brief.gold_examples.linkedin_post.slice(0,3).join('\n---\n') + '\n\n' : '')
      + 'Write a LinkedIn post. Hook-led opening, 150-250 words, first-person founder voice. Plain text only, no hashtags unless natural.'
  },
  {
    format: 'blog',
    systemPrompt: base + (brief.gold_examples.blog && brief.gold_examples.blog.length ? 'GOLD EXAMPLES:\n' + brief.gold_examples.blog.slice(0,3).join('\n---\n') + '\n\n' : '')
      + 'Write a long-form blog post. 800-1200 words. Include a headline, introduction, 3-4 subheadings with body paragraphs, and a conclusion.'
  },
  {
    format: 'video_guide',
    systemPrompt: base + (brief.gold_examples.video_guide && brief.gold_examples.video_guide.length ? 'GOLD EXAMPLES:\n' + brief.gold_examples.video_guide.slice(0,3).join('\n---\n') + '\n\n' : '')
      + 'Write a video guide for the founder to record. Include: hook (first 10 seconds), 3-5 key points with talking points under each, and a closing call to action. Plain text, easy to read off-camera.'
  },
  {
    format: 'carousel',
    systemPrompt: base + (brief.gold_examples.carousel && brief.gold_examples.carousel.length ? 'GOLD EXAMPLES:\n' + JSON.stringify(brief.gold_examples.carousel.slice(0,2)) + '\n\n' : '')
      + 'Return ONLY a valid JSON object with this exact structure: { "cover": { "headline": "...", "subheadline": "..." }, "slides": [ { "headline": "...", "body": "..." } ] }. Include 6-8 slides. These render as image slides, so keep text short: cover headline max 8 words, cover subheadline max 12 words, each slide headline max 8 words, each slide body max 15 words. Punchy and concrete, no filler. No text outside the JSON.'
  }
];

return formats.filter(f => toGenerate.includes(f.format)).map(f => ({ json: {
  ...f,
  story_id: brief.story_id,
  brand_id: brief.brand_id,
  colour_primary: brief.colour_primary,
  colour_secondary: brief.colour_secondary,
  colour_accent: brief.colour_accent,
  banned_patterns: brief.banned_patterns,
  low_context: brief.low_context
} }));

const gens = $input.all();
const srcs = $('Create Format Items').all();
return gens.map((g, idx) => {
  const src = srcs[idx].json;
  const format = src.format;
  let raw = g.json.output || (g.json.choices && g.json.choices[0] && g.json.choices[0].message && g.json.choices[0].message.content) || (g.json.content && g.json.content[0] && g.json.content[0].text) || g.json.text || '';
  raw = raw.replace(/\s*[\u2014\u2013]\s*/g, ', ');
  let body_text = raw;
  let carousel_json = null;
  if (format === 'carousel') {
    try {
      const cleaned = raw.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```\s*$/i,'').trim();
      carousel_json = JSON.parse(cleaned);
      body_text = JSON.stringify(carousel_json);
    } catch(e) { body_text = raw; }
  }
  return { json: {
    format, body_text, carousel_json,
    story_id: src.story_id,
    brand_id: src.brand_id,
    colour_primary: src.colour_primary,
    colour_secondary: src.colour_secondary,
    colour_accent: src.colour_accent,
    banned_patterns: src.banned_patterns,
    low_context: src.low_context
  } };
});

const c = $input.first().json;
const cj = c.carousel_json || {};
const stamp = Date.now();
// hex -> plain-English colour description, so each brand's own palette drives the
// slide design without ever printing a hex code onto the image.
function describe(hex){
  hex = (hex||'').replace('#','').trim();
  if (hex.length===3) hex = hex.split('').map(x=>x+x).join('');
  if (!/^[0-9a-fA-F]{6}$/.test(hex)) return 'neutral grey';
  const r=parseInt(hex.slice(0,2),16)/255, g=parseInt(hex.slice(2,4),16)/255, b=parseInt(hex.slice(4,6),16)/255;
  const mx=Math.max(r,g,b), mn=Math.min(r,g,b), l=(mx+mn)/2, d=mx-mn;
  const sat = d===0 ? 0 : d/(1-Math.abs(2*l-1));
  let h=0;
  if (d!==0){ if(mx===r) h=((g-b)/d)%6; else if(mx===g) h=(b-r)/d+2; else h=(r-g)/d+4; h*=60; if(h<0) h+=360; }
  if (sat<0.18){
    if(l<0.15) return 'near-black charcoal';
    if(l<0.35) return 'dark charcoal grey';
    if(l<0.62) return 'medium grey';
    if(l<0.85) return 'soft light grey';
    return 'off-white';
  }
  const fam = h<15?'red':h<45?'orange':h<70?'amber yellow':h<95?'lime green':h<150?'green':h<185?'teal':h<215?'sky blue':h<255?'blue':h<280?'indigo':h<320?'purple':h<345?'magenta pink':'red';
  if ((fam==='blue'||fam==='sky blue') && l<0.32) return 'deep navy blue';
  const lw = l<0.2?'very dark ':l<0.38?'deep ':l<0.6?'':l<0.78?'light ':'pale ';
  const sw = sat<0.35?'muted ':sat>0.72?'vivid ':'';
  return (lw+sw+fam).trim();
}
const bg = describe(c.colour_accent || '#0B1F3A');
const hl = describe(c.colour_primary || '#2D6CDF');
const bd = describe(c.colour_secondary || '#CFD4DB');
const slides = [];
if (cj.cover) slides.push({ kind:'cover', headline: cj.cover.headline || '', body: cj.cover.subheadline || '' });
(cj.slides || []).forEach(s => slides.push({ kind:'slide', headline: s.headline || '', body: s.body || '' }));
return slides.map((s, i) => {
  const prompt = 'Design a single LinkedIn/Instagram carousel ' + (s.kind==='cover'?'COVER ':'') +
    'slide as a finished, ready-to-post PORTRAIT 4:5 graphic (taller than wide). Clean modern professional B2B design. ' +
    'Colour scheme: ' + bg + ' background, a bold ' + hl + ' for the headline, and ' + bd + ' for the body text. ' +
    'Render ONLY the exact headline and body text given below - no other words, labels, codes, captions or watermarks. Spell every word exactly and correctly.\n' +
    'HEADLINE: ' + s.headline + '\nBODY: ' + s.body + '\n' +
    'Generous margins, strong typographic hierarchy, heavy sans-serif headline, lighter body beneath. ' +
    'Subtle geometric accent in ' + hl + '. No logos, no photographs of people. High contrast, perfectly legible spelling, uncluttered.';
  return { json: {
    slide_index: i, n_slides: slides.length,
    prompt, path: c.story_id + '/' + stamp + '-' + i + '.png',
    format:'carousel', body_text: c.body_text, carousel_json: c.carousel_json,
    story_id: c.story_id, brand_id: c.brand_id,
    colour_primary: c.colour_primary, colour_secondary: c.colour_secondary, colour_accent: c.colour_accent,
    banned_patterns: c.banned_patterns, low_context: c.low_context
  } };
});

const gens = $input.all();
const src = $('Explode Slides').all();
return gens.map((g, i) => {
  const s = src[i].json;
  const parts = ((((g.json.candidates || [])[0] || {}).content || {}).parts) || [];
  const img = parts.find(p => p.inlineData);
  const out = { json: { ...s, rendered: !!img } };
  if (img) out.binary = { data: { data: img.inlineData.data, mimeType:'image/png', fileName: s.path.split('/').pop() } };
  return out;
});

const ups = $input.all();
const src = $('Attach Slide Binary').all();
const base = src[0].json;
const PUB = 'https://YOUR_PROJECT.supabase.co/storage/v1/object/public/';
const urls = [];
ups.forEach((u, i) => {
  const key = u.json && u.json.Key;
  if (key && src[i].json.rendered) urls.push(PUB + key);
});
return [{ json: {
  format:'carousel', body_text: base.body_text, carousel_json: base.carousel_json,
  story_id: base.story_id, brand_id: base.brand_id,
  colour_primary: base.colour_primary, colour_secondary: base.colour_secondary, colour_accent: base.colour_accent,
  banned_patterns: base.banned_patterns, low_context: base.low_context,
  carousel_image_urls: urls,
  carousel_partial: urls.length < src.length
} }];

const items = $input.all();
return items.map(item => {
  const d = item.json;
  const patterns = d.banned_patterns || [];
  const body = (d.body_text || '').toLowerCase();
  const flagged = patterns.filter(p => body.includes(p.toLowerCase()));
  return { json: { ...d, banned_flag: flagged.length > 0, banned_matches: flagged } };
});

const scores = $input.all();
const pieces = $('Banned Patterns Check').all();
return scores.map((s, idx) => {
  const d = pieces[idx].json;
  const raw = s.json.output || (s.json.choices && s.json.choices[0] && s.json.choices[0].message && s.json.choices[0].message.content) || (s.json.content && s.json.content[0] && s.json.content[0].text) || s.json.text || '';
  let quality_score = 0;
  try {
    const cleaned = raw.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```\s*$/i,'').trim();
    quality_score = JSON.parse(cleaned).score || 0;
  } catch(e) {}
  const low_quality = quality_score < 6;
  const status = low_quality ? 'low_quality' : 'draft';
  return { json: {
    format: d.format,
    body_text: d.body_text,
    story_id: d.story_id,
    brand_id: d.brand_id,
    quality_score,
    status,
    low_quality,
    low_context: d.low_context,
    carousel_partial: d.carousel_partial || false,
    carousel_image_urls: d.carousel_image_urls || [],
    banned_flag: d.banned_flag || false
  } };
});

const items = $input.all();
const content_piece_ids = items.map(i => i.json.id);
const story_id = items[0].json.story_id;
const ALL = ['linkedin_post','blog','video_guide','carousel'];
const existing = $('Fetch Existing Pieces').all().map(i => i.json && i.json.format).filter(Boolean);
const generated = items.map(i => i.json.format);
const total = new Set([...existing, ...generated]);
const story_status = total.size >= ALL.length ? 'processed' : 'new';
return [{ json: { story_id, content_piece_ids, story_status } }];
